import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Un po' di storia","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffea.md","filePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffea.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/ff/ffea.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="un-po-di-storia" tabindex="-1">Un po&#39; di storia <a class="header-anchor" href="#un-po-di-storia" aria-label="Permalink to “Un po&#39; di storia”">​</a></h1><blockquote><p>Useremo i termini postulato ed assioma come sinonimi sebbene il postulato sia un enunciato definito come vero mentre l&#39;assioma è considerato un fatto evidente.</p></blockquote><p>Il quinto postulato di Euclide fin dalla sua nascita fu guardato con sospetto dai matematici: infatti mentre per la perpendicolarità si può dimostrare che <strong>per un punto si può mandare una sola perpendicolare ad una retta data</strong> la stessa cosa non si riesce a fare per il parallelismo.</p><p>Ci furono vari tentativi (per più di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2000</mn></mrow><annotation encoding="application/x-tex">2000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2000</span></span></span></span> anni) per poterlo dimostrare, ma senza ottenere risultati, finché attorno al <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1870</mn></mrow><annotation encoding="application/x-tex">1870</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1870</span></span></span></span> furono proposti vari modelli di geometrie in cui erano validi tutti i postulati eccetto quello delle parallele. Fu una rivoluzione, perché mentre prima si pensava che la matematica derivasse dal mondo reale (e quindi i postulati fossero le basi del mondo reale) da quel momento in poi si svilupparono vari tipi di matematiche valide di per sé senza bisogno di collegamenti con il mondo reale stesso.</p><blockquote><p>Molti autorevoli matematici ed anche dei moderni testi di geometria hanno sostituito la definizione di rette parallele in questo modo: <strong>due rette si dicono parallele quando sono equidistanti</strong> credendo così di superare lo scoglio del quinto postulato; però in questo modo devono spiegare cosa intendano per &quot;equidistanti&quot; e non è una cosa semplice, e, in pratica, si torna alle stesse difficoltà.</p></blockquote>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};